<script setup lang="ts">
import {ref,onMounted,watch,computed} from 'vue'
import {useRoute} from 'vue-router'
import {ArrowLeft,ArrowUpRight,MapPin,ExternalLink,Clapperboard,Landmark,Clock3,Ticket,Navigation} from 'lucide-vue-next'
import {api} from '../api'
import {currentHour} from '../presentation'
import type {Scenic,Network,Crowds} from '../types'
import ScenicCover from '../components/ScenicCover.vue'
import InternalMap from '../components/InternalMap.vue'
import ExternalMap from '../components/ExternalMap.vue'
import DestinationActions from '../components/DestinationActions.vue'
import DetailMedia from '../components/DetailMedia.vue'
import DetailAsk from '../components/DetailAsk.vue'
import {journey,loadJourney} from '../journey'
import {useDetailObject} from '../detailObject'
const route=useRoute(),scenic=ref<Scenic>(),network=ref<Network>(),crowds=ref<Crowds>(),busy=ref(true),error=ref(''),mapError=ref(''),tab=ref('外部位置地图')
const {object}=useDetailObject('scenic',()=>String(route.params.id))
const children=computed(()=>object.value?.fact_id?journey.catalog.filter(x=>x.record.kind==='place'&&x.record.parent_place_id===object.value!.fact_id):[])
let version=0
async function load(){const v=++version;busy.value=true;error.value='';mapError.value='';scenic.value=undefined;network.value=undefined;crowds.value=undefined;tab.value='外部位置地图';try{const s=await api.scenic(String(route.params.id));if(v!==version)return;scenic.value=s;if(s.internal_map){try{const[n,c]=await Promise.all([api.network(s.id),api.crowds(s.id,'reported',currentHour())]);if(v===version){network.value=n;crowds.value=c}}catch(e){if(v===version)mapError.value=(e as Error).message}}}catch(e){if(v===version)error.value=(e as Error).message}finally{if(v===version)busy.value=false}}
onMounted(()=>{void load();void loadJourney()});watch(()=>route.params.id,load)
</script>
<template><div class="page editorial-detail scenic-detail-page"><RouterLink to="/" class="back-link"><ArrowLeft :size="16"/>返回发现</RouterLink><div v-if="busy" class="state" role="status"><span class="spinner"/>正在载入景区…</div><div v-else-if="error" class="error-state" role="alert">{{error}} <button @click="load">重试</button></div><template v-else-if="scenic"><figure class="scenic-detail-cover"><ScenicCover :id="scenic.id" :name="scenic.name" :theme="scenic.theme" eager/><figcaption>主题插画</figcaption></figure><header class="editorial-title"><span class="tiny-caption">{{scenic.category}}</span><h1>{{scenic.name}}</h1><p>{{scenic.intro.split('。')[0]+'。'}}</p><DestinationActions kind="scenic" :id="scenic.id" :name="scenic.name"/></header><nav class="detail-section-nav" aria-label="景区详情章节"><a href="#scenic-highlights">看点</a><a href="#scenic-media">图集影像</a><a href="#scenic-shows">演出</a><a href="#scenic-map">地图</a></nav><section id="scenic-highlights" class="editorial-section"><div class="detail-section-title"><h2>在这里，慢慢看</h2><Landmark :size="21" :stroke-width="1.3"/></div><div class="detail-highlight-grid"><article v-for="h in scenic.highlights" :key="h"><span class="highlight-line"/><h3>{{h}}</h3><p class="pending-copy">详细介绍待添加</p></article></div><div class="detail-section-title subsection"><h2>园内看点</h2><span class="pending-caption" v-if="!children.length">待添加</span></div><div v-if="children.length" class="poi-list"><article v-for="p in children" :key="p.record.fact_id"><RouterLink :to="'/place/'+encodeURIComponent(p.record.fact_id)"><MapPin :size="17"/>{{p.record.name}}<ArrowUpRight :size="16"/></RouterLink><small>属于 {{scenic.name}}</small><DestinationActions kind="poi" :id="p.record.fact_id" :name="p.record.name||'园内看点'"/></article></div><div v-else class="content-pending"><MapPin :size="21"/><span>看点位置与游览项目待添加</span></div></section><div id="scenic-media"><DetailMedia kind="scenic" :id="scenic.id" :name="scenic.name"/></div><section id="scenic-shows" class="editorial-section"><div class="detail-section-title"><h2>演出与体验</h2><Clapperboard :size="21" :stroke-width="1.3"/></div><div v-if="!scenic.shows.length" class="content-pending">演出介绍与有效场次待添加</div><article v-for="s in scenic.shows" :key="s.name" class="detail-show"><Clapperboard :size="20"/><div><h3>{{s.name}}</h3><p>{{s.venue}}</p><small>{{s.schedule}}</small><a :href="s.source_url" target="_blank" rel="noopener noreferrer">查看官方介绍 <ExternalLink :size="12"/></a></div></article><RouterLink v-if="scenic.internal_map" :to="'/guide?scenic='+scenic.id" class="text-link">在景区地图中查看场次 <ArrowUpRight :size="15"/></RouterLink></section><section class="editorial-section"><div class="detail-section-title"><h2>游玩信息</h2></div><dl class="detail-fact-grid"><div><dt><Clock3 :size="16"/>建议时长</dt><dd>待添加</dd></div><div><dt><Ticket :size="16"/>开放与票务</dt><dd>待添加</dd></div><div><dt><MapPin :size="16"/>景区位置</dt><dd>{{scenic.address||'待添加'}}</dd></div><div><dt><Navigation :size="16"/>入口指引</dt><dd>待添加</dd></div></dl><a :href="scenic.source_url" target="_blank" rel="noopener noreferrer" class="quiet-link">公开资料来源 · {{scenic.checked_at}} <ExternalLink :size="12"/></a></section><section id="scenic-map" class="editorial-section"><div class="detail-section-title"><h2>找到这一处</h2></div><div class="discovery-tabs"><button v-for="t in ['外部位置地图','内部示意地图']" :key="t" :class="{active:tab===t}" :aria-pressed="tab===t" @click="tab=t">{{t}}</button></div><InternalMap v-if="tab==='内部示意地图'&&network" :network="network" :crowds="crowds?.nodes"/><div v-else-if="tab==='内部示意地图'" class="content-pending">{{mapError||'园内核验路网待添加'}}</div><ExternalMap v-else :key="scenic.id" :name="scenic.name" :address="scenic.address"/></section><DetailAsk kind="scenic" :id="scenic.id" :name="scenic.name"/><RouterLink class="detail-basket-link" to="/basket">整理旅行素材篮 <ArrowUpRight :size="17"/></RouterLink></template></div></template>
